WITH lines AS (SELECT id, service, host, log_ts, level, latency_ms, status_code, key, v FROM app_logs LATERAL VIEW EXPLODE(context) li AS key, v), unpacked AS (SELECT id, service, host, log_ts, key, v, SHIFTRIGHT(status_code, 2) AS status_code_high, CAST((status_code & 4) != 0 AS INT) AS is_flagged FROM lines), with_gaps AS (SELECT *, CASE WHEN log_ts - LAG(log_ts) OVER (PARTITION BY service ORDER BY log_ts, id, key) > INTERVAL 30 MINUTES THEN 1 ELSE 0 END AS new_group_flag FROM unpacked), islands AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY service ORDER BY log_ts, id, key ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM with_gaps), with_windows AS (SELECT *, AVG(is_flagged) OVER w_grp AS last7_avg_is_flagged, COUNT(is_flagged) OVER w_grp AS last7_count_is_flagged, SUM(is_flagged) OVER w_grp AS last7_sum_is_flagged FROM islands WINDOW w_grp AS (PARTITION BY key, host ORDER BY session_id, id, key ROWS BETWEEN 6 PRECEDING AND CURRENT ROW)) SELECT id, service, host, key, v, is_flagged, new_group_flag, session_id, last7_avg_is_flagged, CASE WHEN key RLIKE '^(version|region)$' THEN 'CORE' ELSE 'OTHER_ZONE' END AS key_zone FROM with_windows ORDER BY is_flagged DESC NULLS FIRST, key
